dashboard.definition:
{
  "title": "Scenario - OT Rogue Device",
  "description": "Unauthorized contractor laptop in Detroit plant Zone-1 attempts PLC program download, detected and blocked by Cyber Vision policy enforcement",
  "dataSources": {
    "ds_total_events": {
      "type": "ds.search",
      "name": "Scenario Events Over Time",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:*\" demo_id=ot_rogue_device | timechart span=5m count"
      }
    },
    "ds_affected_hosts": {
      "type": "ds.search",
      "name": "Affected Assets",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:*\" demo_id=ot_rogue_device | stats dc(dest_label) as count"
      }
    },
    "ds_security_events": {
      "type": "ds.search",
      "name": "Security Events",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:events\" demo_id=ot_rogue_device family=Security | stats count"
      }
    },
    "ds_duration": {
      "type": "ds.search",
      "name": "Incident Duration",
      "options": {
        "query": "index=fake_tshrt demo_id=ot_rogue_device | stats min(_time) as start max(_time) as end | eval duration=tostring(end-start, \"duration\") | eval count=duration | fields count"
      }
    },
    "ds_rogue_device": {
      "type": "ds.search",
      "name": "Rogue Device Record",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:devices\" demo_id=ot_rogue_device label=CONTRACTOR-LAPTOP-01 | dedup id | table label, ip{}, mac{}, asset_vendor, asset_model, riskScore, risk_score_severity, vulnerabilitiesCount | rename \"label\" as \"Asset\", \"ip{}\" as \"IP\", \"mac{}\" as \"MAC\", asset_vendor as \"Vendor\", asset_model as \"Model\", riskScore as \"Risk Score\", risk_score_severity as \"Severity\", vulnerabilitiesCount as \"Vulns\""
      }
    },
    "ds_attack_timeline": {
      "type": "ds.search",
      "name": "Attack Timeline by Sourcetype",
      "options": {
        "query": "index=fake_tshrt demo_id=ot_rogue_device | eval source_label=case(match(sourcetype,\"cybervision:devices\"),\"Devices\", match(sourcetype,\"cybervision:events\"),\"Events\", match(sourcetype,\"cybervision:flows\"),\"Flows\", match(sourcetype,\"cybervision:activities\"),\"Activities\", match(sourcetype,\"cybervision:syslog\"),\"Syslog CEF\", 1=1, sourcetype) | timechart span=5m count by source_label"
      }
    },
    "ds_attack_sequence": {
      "type": "ds.search",
      "name": "Attack Sequence",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:events\" demo_id=ot_rogue_device | table _time, type, severity, category, message | sort _time | rename type as \"Event\", severity as \"Sev\", category as \"Category\", message as \"Message\""
      }
    },
    "ds_events_by_type": {
      "type": "ds.search",
      "name": "Events by Type",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:events\" demo_id=ot_rogue_device | stats count by type | sort -count | rename type as \"Event Type\""
      }
    },
    "ds_rogue_flows": {
      "type": "ds.search",
      "name": "Rogue Network Flows",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:flows\" demo_id=ot_rogue_device | stats count, sum(bytes) as bytes_total by left.label, right.label, protocol | sort -count | head 15 | rename left.label as \"Source\", right.label as \"Destination\", protocol as \"Protocol\", bytes_total as \"Bytes\""
      }
    },
    "ds_rogue_activities": {
      "type": "ds.search",
      "name": "Protocol Activities",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:activities\" demo_id=ot_rogue_device | table _time, left.label, right.label, tags{}.label | sort _time | head 20 | rename left.label as \"Source\", right.label as \"Destination\", \"tags{}.label\" as \"Tags\""
      }
    },
    "ds_syslog_cef": {
      "type": "ds.search",
      "name": "CEF Syslog Stream",
      "options": {
        "query": "index=fake_tshrt sourcetype=\"FAKE:cisco:cybervision:syslog\" demo_id=ot_rogue_device | table _time, severity, cat, message | sort _time | rename severity as \"Severity\", cat as \"Category\", message as \"CEF Message\""
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Scenario — OT Rogue Device\n\n**demo_id:** `ot_rogue_device`  |  **Category:** Attack (OT/ICS)  |  **Duration:** Day 8 14:00–16:30 (~2.5 hours)  |  **Severity:** High  |  **Outcome:** BLOCKED by CV policy enforcement\n\n**Target:** PLC-PRINT-01 (Siemens S7-1500, Zone-1 Printing Line, criticalness=Critical)\n\n**Rogue Asset:** CONTRACTOR-LAPTOP-01 (Dell Latitude 5540, 10.40.100.200) — plugged directly into Zone-1 OT network in violation of plant change-management policy.\n\n**Attack Summary:**\n1. **14:00** — New device detected on Zone-1 (unauthorized, no change ticket)\n2. **14:05** — Network scan: all PLCs probed on Modbus/S7/CIP\n3. **14:20** — Modbus variable read/write from contractor to PLC-PACK-01\n4. **14:35** — S7Plus program upload from PLC-PRINT-01\n5. **14:50** — **S7Plus program DOWNLOAD attempt BLOCKED** by CV policy\n6. **15:10** — Cleartext Modbus credential observed\n7. **16:30** — Laptop physically disconnected by operations team",
        "fontColor": "#C3CBD4"
      }
    },
    "viz_kpi_total_events": {
      "type": "splunk.singlevalue",
      "title": "Scenario Events",
      "dataSources": { "primary": "ds_total_events" },
      "options": {
        "majorValue": "> sparklineValues | lastPoint()",
        "sparklineValues": "> primary | seriesByName('count')",
        "sparklineDisplay": "below",
        "majorColor": "#F1813F",
        "backgroundColor": "transparent",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#F1813F"
      }
    },
    "viz_kpi_hosts": {
      "type": "splunk.singlevalue",
      "title": "Affected Assets",
      "dataSources": { "primary": "ds_affected_hosts" },
      "options": {
        "majorValue": "> primary | seriesByName('count') | lastPoint()",
        "majorColor": "#00D2FF",
        "backgroundColor": "transparent",
        "sparklineDisplay": "off"
      }
    },
    "viz_kpi_security": {
      "type": "splunk.singlevalue",
      "title": "Security Events",
      "dataSources": { "primary": "ds_security_events" },
      "options": {
        "majorValue": "> primary | seriesByName('count') | lastPoint()",
        "majorColor": "#DC4E41",
        "backgroundColor": "transparent",
        "sparklineDisplay": "off"
      }
    },
    "viz_kpi_duration": {
      "type": "splunk.singlevalue",
      "title": "Duration",
      "dataSources": { "primary": "ds_duration" },
      "options": {
        "majorValue": "> primary | seriesByName('count') | lastPoint()",
        "majorColor": "#F8BE34",
        "backgroundColor": "transparent",
        "sparklineDisplay": "off"
      }
    },
    "viz_rogue_device": {
      "type": "splunk.table",
      "title": "Rogue Device (Cyber Vision Inventory Record)",
      "dataSources": { "primary": "ds_rogue_device" },
      "options": { "count": 5, "showRowNumbers": false },
      "showProgressBar": true
    },
    "viz_attack_timeline": {
      "type": "splunk.area",
      "title": "Attack Timeline (5-minute buckets)",
      "dataSources": { "primary": "ds_attack_timeline" },
      "options": {
        "stackMode": "stacked",
        "legendDisplay": "right",
        "nullValueDisplay": "zero",
        "areaOpacity": 0.7,
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "Events / 5-min",
        "yAxisTitleVisibility": "show",
        "yAxisAbbreviation": "auto",
        "seriesColors": ["#DC4E41", "#F1813F", "#00D2FF", "#7B56DB", "#53A051"]
      },
      "showProgressBar": true
    },
    "viz_events_by_type": {
      "type": "splunk.bar",
      "title": "Events by Type",
      "dataSources": { "primary": "ds_events_by_type" },
      "options": {
        "seriesColors": ["#DC4E41"],
        "legendDisplay": "off",
        "xAxisTitleText": "Count",
        "xAxisTitleVisibility": "show",
        "yAxisTitleVisibility": "hide",
        "backgroundColor": "transparent"
      }
    },
    "viz_rogue_flows": {
      "type": "splunk.table",
      "title": "Rogue Network Flows (Contractor → PLCs)",
      "dataSources": { "primary": "ds_rogue_flows" },
      "options": { "count": 15, "showRowNumbers": false },
      "showProgressBar": true
    },
    "viz_rogue_activities": {
      "type": "splunk.table",
      "title": "Protocol Activities",
      "dataSources": { "primary": "ds_rogue_activities" },
      "options": { "count": 20, "showRowNumbers": false },
      "showProgressBar": true
    },
    "viz_sequence_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Attack Sequence (Cyber Vision Events)",
        "fontColor": "#C3CBD4"
      }
    },
    "viz_attack_sequence": {
      "type": "splunk.table",
      "title": "Event-by-Event Attack Sequence",
      "dataSources": { "primary": "ds_attack_sequence" },
      "options": { "count": 50, "showRowNumbers": false },
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_cef_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### CEF Syslog Stream (real-time feed to SIEM)",
        "fontColor": "#C3CBD4"
      }
    },
    "viz_cef": {
      "type": "splunk.table",
      "title": "CEF Syslog",
      "dataSources": { "primary": "ds_syslog_cef" },
      "options": { "count": 30, "showRowNumbers": false },
      "showProgressBar": true
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time Range",
      "options": {
        "token": "global_time",
        "defaultValue": "1767225600,1769904000"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "globalInputs": ["input_global_trp"],
    "structure": [
      { "item": "viz_header",          "type": "block", "position": { "x": 0,    "y": 0,    "w": 1200, "h": 320 } },
      { "item": "viz_kpi_total_events","type": "block", "position": { "x": 0,    "y": 320,  "w": 300,  "h": 120 } },
      { "item": "viz_kpi_hosts",       "type": "block", "position": { "x": 300,  "y": 320,  "w": 300,  "h": 120 } },
      { "item": "viz_kpi_security",    "type": "block", "position": { "x": 600,  "y": 320,  "w": 300,  "h": 120 } },
      { "item": "viz_kpi_duration",    "type": "block", "position": { "x": 900,  "y": 320,  "w": 300,  "h": 120 } },
      { "item": "viz_rogue_device",    "type": "block", "position": { "x": 0,    "y": 440,  "w": 1200, "h": 160 } },
      { "item": "viz_attack_timeline", "type": "block", "position": { "x": 0,    "y": 600,  "w": 750,  "h": 350 } },
      { "item": "viz_events_by_type",  "type": "block", "position": { "x": 750,  "y": 600,  "w": 450,  "h": 350 } },
      { "item": "viz_rogue_flows",     "type": "block", "position": { "x": 0,    "y": 950,  "w": 600,  "h": 320 } },
      { "item": "viz_rogue_activities","type": "block", "position": { "x": 600,  "y": 950,  "w": 600,  "h": 320 } },
      { "item": "viz_sequence_header", "type": "block", "position": { "x": 0,    "y": 1270, "w": 1200, "h": 50  } },
      { "item": "viz_attack_sequence", "type": "block", "position": { "x": 0,    "y": 1320, "w": 1200, "h": 420 } },
      { "item": "viz_cef_header",      "type": "block", "position": { "x": 0,    "y": 1740, "w": 1200, "h": 50  } },
      { "item": "viz_cef",             "type": "block", "position": { "x": 0,    "y": 1790, "w": 1200, "h": 380 } }
    ]
  }
}
